/**
 * Renders app/public/og-image.png (1200×630, seo-geo §3) in the forge look (PLAN T-12): the light page
 * background, the meeple app icon, the name in the body colour, the tagline in the secondary colour and
 * one accent bar — colours from design/tokens.css and app.config.ts `accent` (scripts/tokens.ts), like
 * the sibling apps' images. Run `pnpm og-image` after the name, tagline, accent or logo change, and commit
 * the PNG (it is not regenerated by the build). Uses the Playwright Chromium the e2e tests already
 * install — no extra dependency.
 */
import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { chromium } from "@playwright/test";
import { app } from "../app.config.ts";
import { OG_IMAGE, escapeHtml } from "./seo.ts";
import { TEXT_COLOURS, THEME_BACKGROUND } from "./tokens.ts";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const logo = readFileSync(join(root, "app", "public", "favicon.svg"), "utf8");

// Layout values of a one-off image, not UI: the system font stack matches the app; 1 CSS px = 1 image px.
const html = `<!DOCTYPE html><html><body style="margin:0">
<div style="width:${String(OG_IMAGE.width)}px;height:${String(OG_IMAGE.height)}px;box-sizing:border-box;padding:96px;display:flex;align-items:center;gap:72px;background:${THEME_BACKGROUND.light};font-family:-apple-system,BlinkMacSystemFont,'Inter','Segoe UI',system-ui,sans-serif">
  <div style="width:280px;height:280px;flex:none;border-radius:64px;box-shadow:0 8px 24px rgb(0 0 0 / 0.08),0 24px 64px rgb(0 0 0 / 0.04)">${logo.replace("<svg ", '<svg width="280" height="280" ')}</div>
  <div>
    <div style="font-size:96px;font-weight:700;line-height:1.05;letter-spacing:-0.022em;color:${TEXT_COLOURS.text.light}">${escapeHtml(app.name)}</div>
    <div style="margin-top:28px;width:96px;height:10px;border-radius:5px;background:${app.accent}"></div>
    <div style="margin-top:28px;font-size:42px;line-height:1.25;color:${TEXT_COLOURS.secondary.light};text-wrap:balance">${escapeHtml(app.tagline)}</div>
  </div>
</div></body></html>`;

const browser = await chromium.launch();
try {
  const page = await browser.newPage({ viewport: { width: OG_IMAGE.width, height: OG_IMAGE.height }, deviceScaleFactor: 1 });
  await page.setContent(html);
  const file = join(root, "app", "public", OG_IMAGE.file);
  await page.screenshot({ path: file, type: "png" });
  console.log(`og-image: wrote ${file}`);
} finally {
  await browser.close();
}
